#Requires -Version 7.0
#Requires -Modules @{ ModuleName = 'Pester'; ModuleVersion = '5.0.0' }, powershell-yaml
# The example ARM parameter files of config/azure/arm-templates/examples are generated by config/variables/scripts/New-ArmParameterExample.ps1
# from the example infrastructure files, with the deployment's own builder (New-AzlArmParameterSet, ConvertTo-AzlArmParameterFile). The tests run
# its -Check (every example is what the builder writes, and no other parameter file is there) and check that the examples hold example values only.
# Reads files only; nothing runs against Azure.
# Run: Import-Module Pester -RequiredVersion 5.9.1; Invoke-Pester ./tests/arm-deployment/ArmParameterExamples.Tests.ps1
[Diagnostics.CodeAnalysis.SuppressMessageAttribute('PSUseDeclaredVarsMoreThanAssignments', '', Justification = 'Pester scopes.')]
param()

BeforeDiscovery {
    $repo = [IO.Path]::GetFullPath([IO.Path]::Combine($PSScriptRoot, '..', '..'))
    $exampleCase = @(Get-ChildItem -LiteralPath ([IO.Path]::Combine($repo, 'config', 'azure', 'arm-templates', 'examples')) -File -Filter '*.parameters.json' |
            ForEach-Object { @{ Name = $_.Name; Path = $_.FullName } })
}

BeforeAll {
    $script:Repo = [IO.Path]::GetFullPath([IO.Path]::Combine($PSScriptRoot, '..', '..'))
    $script:Generator = [IO.Path]::Combine($script:Repo, 'config', 'variables', 'scripts', 'New-ArmParameterExample.ps1')
}

Describe 'The ARM parameter examples are generated' {
    It 'New-ArmParameterExample.ps1 -Check passes (every example is what the builder writes from its infrastructure file)' {
        $out = & pwsh -NoProfile -File $script:Generator -Check 2>&1
        $LASTEXITCODE | Should -Be 0 -Because ($out -join "`n")
    }
    It 'there are examples for Active Directory, local identity, rack aware and a SAN' -ForEach @(@{ Names = @($exampleCase | ForEach-Object { $_.Name }) }) {
        $Names | Should -Contain 'active-directory-s2d-switched.parameters.json'
        $Names | Should -Contain 'local-identity-s2d-switchless.parameters.json'
        $Names | Should -Contain 'rack-aware-s2d.parameters.json'
        $Names | Should -Contain 'fibre-channel-san.parameters.json'
    }
    It 'no hand-written parameter file is left in config/azure/arm-templates (cluster-deployment and the old example folders are gone)' {
        @(Get-ChildItem -LiteralPath ([IO.Path]::Combine($script:Repo, 'config', 'azure', 'arm-templates')) -Recurse -File -Filter 'azuredeploy*.json') | Should -BeNullOrEmpty
    }
}

Describe '<Name> holds example values only' -ForEach $exampleCase {
    BeforeAll { $script:Text = Get-Content -LiteralPath $Path -Raw; $script:Json = $script:Text | ConvertFrom-Json -AsHashtable -Depth 100 }
    It 'is an ARM deployment parameters file' {
        $script:Json['$schema'] | Should -Match 'deploymentParameters\.json'
        $script:Json.parameters.Count | Should -BeGreaterThan 30
    }
    It 'has only documentation addresses (RFC 5737) and the zero GUID' {
        @([regex]::Matches($script:Text, '\b\d{1,3}(\.\d{1,3}){3}\b') | ForEach-Object { $_.Value } |
                Where-Object { $_ -notmatch '^(192\.0\.2|198\.51\.100|203\.0\.113)\.' -and $_ -notin '1.0.0.0', '255.255.255.0' }) | Should -BeNullOrEmpty
        @([regex]::Matches($script:Text, '[0-9a-fA-F]{8}-([0-9a-fA-F]{4}-){3}[0-9a-fA-F]{12}') | ForEach-Object { $_.Value } | Where-Object { $_ -ne '00000000-0000-0000-0000-000000000000' }) | Should -BeNullOrEmpty
        $script:Text | Should -Not -Match '(?i)contoso'
    }
    It 'gives every secret as a Key Vault reference, never a value' {
        foreach ($name in 'localAdminPassword', 'AzureStackLCMAdminPassword', 'AzureStackLCMAdminPasssword') {
            if ($script:Json.parameters.Contains($name)) { $script:Json.parameters[$name].Contains('reference') | Should -BeTrue -Because $name }
        }
    }
}
